Definition sm_ok (ps : SR.post_spec) (i : nat) (X : kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20}^3!2+7!2+7+8+9+9$ps;R+N$i;R+O$X;R+@!2'P!4'Q'R'B'C#1!:'S'T'U!1'V#30!4'W'X#2'Y!1,>!2+7+8+8!4'W!1+=1#2'Z!1,>1!1,1|10;}^80#1").
Definition isSome {A} (o : option A) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S01<scd;$A;R{cd;$o;R!1+[#1-[RN$o;R!1+[#2+\#12$a;R#2,^0,^1").
Definition has := CC.has_cell.
Definition CPF0 : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!2+7+8+9!2+70+8|<1d0;|30;!3,<1!4,60+8!4,6+8+9!1,^2}2!1,;2!1,4!1,12!3,<1!4,60+8!4,6+8+9'^3!1,1|828;!1,4!1,13!1,>1").
Definition FRM : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!2+7+8+9!2+70+8!1,1|500;!3,<1!4,60+8!4,6+8+9':,0!1,4!1,1|48;!3,<1!4,60+8!4,6+8+9':2!1,4!1,1|758;!3,<1!4,60+8!4,6+8+9!1'^4':'F!1,42!1,>1").
Definition FLR : SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!4,6!2+7+8+9+8!4,6+8+9'H,0!1,4!1,1,G").
Definition CPF1 : list SGP.region := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'J'^5'^6'^7").                  (* [comment removed for export] *)
Definition CPF2 : list SGP.region := CPF0 ++ FRM ++ [FLR].         (* [comment removed for export] *)
Definition SHB (k v : Z) : kentry := KWord (SA (CHA.SRL3 FE) (SBz + k)) 1 (ELit v).      (* [comment removed for export] *)
(* [comment removed for export] *)
Definition sink_call (chk : CC.cutpoint -> SR.post_spec -> CC.cutpoint -> CA.blocks -> list (expr * Z * Z) -> CA.blocks -> list (expr * Z * Z) -> option CH2.cinfo)
           (i j : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) : bool :=
  match CH2.ret_of G.RETS i k with
  | Some j' => (Nat.eqb j' j && match nth_error G.CPS j with
                               | Some cj => isSome (chk c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []))
                               | None => false end)%bool
  | None => false
  end.
Definition APPCHK := EBA.sink_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI STAT S2E FLN.
Definition PBCHK := EBA.pushb_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI STAT S2E FLN.
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  let cells := SR.ps_cells ps in
  (Nat.leb GT.NF (CC.cp_nx c) && CH2.blocks_eqb (nth i G.BLS []) [] && Nat.ltb i 8)%bool &&
  match t with
  | CC.TGoto j s =>
      ((Nat.eqb i 4 || Nat.eqb i 7) && CBA.regions_eqb (CC.cp_F c) CPF1 && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
       && expr_eqb (CC.esubstL GT.NF s FLE) FLE && expr_eqb (CC.esubstL GT.NF s FE) FE
       && (if Nat.eqb j 1 then       (* [comment removed for export] *)
             if Nat.eqb i 7 then expr_eqb (CC.esubstL GT.NF s KE) INDENT && CBA.has_range cells DE 1 1024 && CBA.has_range cells INDENT 1 4096
             else expr_eqb (CC.esubstL GT.NF s KE) (EAlu Instr.ALU_ADD KE (ELit (-1))) && CBA.has_range cells (EAlu Instr.ALU_ADD KE (ELit (-1))) 1 4096
           else Nat.eqb j 2 && Nat.eqb i 4 && expr_eqb (CC.esubstL GT.NF s KE) KE && CBA.has_range cells KE 1 1))%bool      (* [comment removed for export] *)
  | CC.TOther pc =>
      if Z.eqb pc PC_SM2 then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => (Z.eqb (SR.ps_pc ps) PC_SM2 && Nat.eqb i 0 && Nat.eqb j 3 && CBA.regions_eqb (CC.cp_F c) CPF0
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 (nth i G.BLS []) (nth i FFS []) [] (List.filter (sm_ok ps i) (CC.cp_know cj)) None c ps cj
                                             (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => (Nat.eqb (CH2.ci_nx ci) 48 && Z.eqb (CH2.ci_csp ci) (-160))%bool | None => false end)%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_MC then
        match CH2.ret_of G.RETS i k with
        | Some j => match nth_error G.CPS j with
                    | Some cj => let o := (if Nat.eqb i 3 then 32 else 96) in
                                 (Z.eqb (SR.ps_pc ps) PC_MC && ((Nat.eqb i 3 && Nat.eqb j 5) || (Nat.eqb i 5 && Nat.eqb j 6)) && CBA.regions_eqb (CC.cp_F c) CPF1
                                  && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                  && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 2560 0 (nth i G.BLS []) (nth i FFS []) (COPY_W o) (NEWS_C o) None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                     | Some ci => Z.eqb (CH2.ci_csp ci) (-176) | None => false end
                                  && CL.ps_reg_is ps 10 (EAlu Instr.ALU_ADD FE (ELit o)) && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD VE (ELit 48)) && CL.ps_reg_is ps 12 (ELit 24)
                                  && has cells (KWord (SA VE 48) 8 (ELit 2562)) && has cells (KWord (SA VE 56) 8 (ELit 0)) && has cells (KWord (SA VE 64) 8 (ELit 0))
                                  && has cells (SHB (o / 8) 0) && has cells (SHB (o / 8 + 1) 0) && has cells (SHB (o / 8 + 2) 0)
                                  && has cells (KWord (SA FE 248) 8 FLE))%bool
                    | None => false end
        | None => false end
      else if Z.eqb pc PC_APPEND then
        (Z.eqb (SR.ps_pc ps) PC_APPEND && Nat.eqb i 6 && sink_call APPCHK i 7 c k ps && CBA.regions_eqb (CC.cp_F c) CPF1 && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
         && CL.ps_reg_is ps 11 (EAlu Instr.ALU_ADD FE (ELit 33)) && CL.ps_reg_is ps 12 (ELit 1)
         && has cells (KWord (SA FE 32) 8 (ELit 2562)) && has cells (SHB 4 0) && has cells (KWord (SA FE 248) 8 FLE))%bool
      else if Z.eqb pc PC_PUSHB then
        (Z.eqb (SR.ps_pc ps) PC_PUSHB && Nat.eqb i 1 && sink_call PBCHK i 4 c k ps && CBA.regions_eqb (CC.cp_F c) CPF1 && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
         && CL.ps_reg_is ps 11 (ELit 32) && has cells (KWord (SA FE 248) 8 FLE) && CBA.has_range cells KE 1 4096)%bool
      else
        (Z.eqb pc RETPC && Nat.eqb i 2 && CBA.exit_base_chk GT.NF RETPC c ps
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0)) && CBA.regions_eqb (CC.cp_F c) CPF2
         && has cells (KWord (SA VE 296) 8 INDENT) && CBA.has_range cells KE 1 1)%bool
  end.
